/// <summary>
/// QR 체크시트 첫 자료 — "체크시트_QR_양식입력.xlsx"(METAL 3정 5S 점검 Sheet Rev.2, 2026-09-25 보완본)의
/// 2_구역·3_점검항목 시트를 옮긴 것. 구역 표가 비어 있을 때만 넣는다. 이후 변경은 관리 화면이나 엑셀 가져오기로 한다.
/// 주 1회 요일·QR 부착 위치·NG 담당부서는 파일에 아직 비어 있어 관리 화면에서 채운다.
/// </summary>
public static class CheckSheetSeed
{
    public static void Run(CleanPotalDbContext db)
    {
        if (db.CheckZones.Any()) return;
        db.CheckZones.AddRange(Zones());
        foreach (var item in Items())
        {
            item.Cycle = item.Timing switch { CheckTimings.Weekly => "매주", CheckTimings.Event => "이벤트", _ => "매일" };
            item.UpdatedBy = "초기 자료";
            db.CheckItems.Add(item);
        }
        db.SaveChanges();
        Console.WriteLine("[seed] QR 체크시트 구역·항목 시드(METAL)");
    }

